from __future__ import annotations

from profile_defaults import SYSTEM_DEFAULTS


def fill_system_defaults(record):
    merged = dict(record)
    for field_name, default_value in SYSTEM_DEFAULTS.items():
        if merged.get(field_name) is None:
            merged[field_name] = default_value
    return merged

