from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    # ``setdefault`` is not sufficient here: a request may explicitly carry
    # null, which means the value is still missing and may be supplied by the
    # profile service.
    for field_name in ("timezone", "currency"):
        if merged.get(field_name) is None:
            profile_value = profile.get(field_name)
            if profile_value is not None:
                merged[field_name] = profile_value
    return merged

