import json
import math
from numbers import Real
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    """Return all local validation errors for a record."""
    if not isinstance(record, dict):
        return ["record must be an object"]

    errors = []
    for field_name in REQUIRED_FIELDS:
        value = record.get(field_name)
        if field_name not in record or value is None:
            errors.append(f"missing required field: {field_name}")

    if "user_id" in record and record["user_id"] is not None:
        if not isinstance(record["user_id"], str) or not record["user_id"].strip():
            errors.append("user_id must be a non-empty string")
    if "amount" in record and record["amount"] is not None:
        amount = record["amount"]
        if isinstance(amount, bool) or not isinstance(amount, Real) or not math.isfinite(amount):
            errors.append("amount must be a finite number")

    return errors


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A profile miss is expected and is handled by system defaults below.
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    failures = []
    for index, record in enumerate(payload):
        errors = validate_record(record)
        if errors:
            failures.append({"index": index, "record": record, "errors": errors})
            continue

        try:
            enriched = enrich(record)
            normalized = normalize(enriched)
        except (TypeError, ValueError) as exc:
            # Normalization errors are local failures and must not reach the
            # transaction API either.
            failures.append({"index": index, "record": record, "errors": [str(exc)]})
            continue

        results.append(send_transaction(normalized))

    return {
        "results": results,
        "failures": failures,
        "summary": {"total": len(payload), "succeeded": len(results), "failed": len(failures)},
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
    }
